from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(4,'division','La division : entière et décimale','1 · Nombres entiers et calculs',
'Quotient · Reste · Quotient décimal exact',
['Poser une division euclidienne et contrôler son résultat.','Poursuivre une division après la virgule.','Choisir entre quotient entier et quotient décimal selon le contexte.'],
['Division euclidienne du CM1 et rangs décimaux.'],[
page(1,'La division euclidienne, bien installée',
bloc('definition',r'Diviser 1\,258 par 6, c’est écrire $1\,258=6\times209+4$ : quotient 209, reste 4, avec un reste toujours plus petit que le diviseur. Le contrôle refait le chemin inverse : $6\times209+4=1\,258$.'),
bloc('savoirfaire',r'Poser proprement : chercher combien de fois le diviseur entre dans les premiers chiffres, abaisser chiffre à chiffre, placer un 0 au quotient quand le chiffre abaissé ne suffit pas : $3\,618:9=402$.','Les zéros du quotient'),
bloc('exemple',r'Selon la question, le même calcul répond différemment : avec 230 œufs et des boîtes de 6, on remplit 38 boîtes ($230=6\times38+2$), mais il faut 39 boîtes pour tout transporter.'),
bloc('attention',r'Un reste se compare toujours au diviseur : si le reste le dépasse, un paquet de plus est possible et la division n’est pas terminée.')),
page(2,'Continuer après la virgule',
bloc('definition',r'Quand le partage doit être exact, la division se poursuit dans les rangs décimaux : $27:4$ donne quotient 6 et reste 3 ; les 3 unités deviennent 30 dixièmes ; $30:4$ donne 7 dixièmes, reste 2 ; les 2 dixièmes deviennent 20 centièmes ; $20:4=5$. Donc $27:4=6{,}75$ exactement.'),
bloc('exemple',r'Avec un dividende décimal, même méthode : $8{,}7:6$. Les 8 unités donnent 1 ; reste 2, soit 27 dixièmes avec le 7 ; $27:6=4$ reste 3, soit 30 centièmes ; $30:6=5$. Donc $8{,}7:6=1{,}45$. La virgule du quotient se place en passant aux dixièmes.'),
bloc('savoirfaire',r'Contrôler un quotient décimal par la multiplication : $6{,}75\times4=27$ et $1{,}45\times6=8{,}7$. Estimer aussi : $27:4$ est entre 6 et 7.','Contrôler le quotient'),
bloc('attention',r'Certains partages ne s’arrêtent jamais : $10:3=3{,}333\ldots$ On s’arrête alors au rang demandé par l’énoncé. Un quotient décimal exact existe quand le reste finit par tomber à zéro.'))
],[
E('Une division posée',r'Poser la division euclidienne de $1\,258$ par 6, écrire l’égalité et la contrôler.',r'Quotient $\res{209}$, reste $\res4$ : $1\,258=6\times209+4$ et $4<6$. Contrôle : $6\times209+4=1\,258$.','Ne pas oublier le zéro du quotient.','assert divmod(1258,6)==(209,4)'),
E('Le zéro au quotient',r'Calculer $3\,618:9$, puis $2\,814:7$.',r'$3\,618:9=\res{402}$ : le 1 abaissé ne suffit pas, d’où le 0. $2\,814:7=\res{402}$ aussi : coïncidence instructive, à contrôler : $402\times7=2\,814$.','Abaisser chiffre à chiffre sans sauter de rang.','assert 3618//9==402 and 3618%9==0 and 2814//7==402 and 2814%7==0'),
E('Après la virgule',r'Calculer le quotient décimal exact de $27:4$.',r'$27:4$ donne 6, reste 3 ; en dixièmes : $30:4=7$, reste 2 ; en centièmes : $20:4=5$. Donc $27:4=\res{6{,}75}$. Contrôle : $6{,}75\times4=27$.','Transformer le reste en rang suivant.','assert Rational(27,4)==Rational("6.75")'),
E('Dividende décimal',r'Calculer $8{,}7:6$.',r'$8:6=1$ reste 2 ; avec le 7 : $27:6=4$ dixièmes, reste 3 ; en centièmes : $30:6=5$. Donc $8{,}7:6=\res{1{,}45}$ ; contrôle : $1{,}45\times6=8{,}7$.','Placer la virgule au passage des dixièmes.','assert Rational("8.7")/6==Rational("1.45")'),
E('Moitiés et quarts décimaux',r'Calculer $9:2$, puis $9:4$.',r'$9:2=\res{4{,}5}$ : la moitié de 9. $9:4=\res{2{,}25}$ : le quart, la moitié de la moitié.','Diviser par 2, une ou deux fois.','assert Rational(9,2)==Rational("4.5") and Rational(9,4)==Rational("2.25")'),
E('Choisir le bon quotient',r'On partage 75 euros entre 4 personnes. On range 75 cahiers dans des cartons de 4. Donner la réponse adaptée à chaque situation.',r'L’argent se partage exactement : $75:4=\res{18{,}75}$ euros chacun. Les cahiers restent entiers : $75=4\times18+3$, soit $\res{18}$ cahiers par carton et 3 cahiers restants. Le contexte choisit le quotient.','Se demander si la grandeur se coupe.','assert Rational(75,4)==Rational("18.75") and divmod(75,4)==(18,3)'),
E('Le reste et l’égalité',r'Sans poser la division, dire si cette égalité décrit une division euclidienne : $507=8\times62+11$. Corriger si besoin.',r'$507=8\times62+11$ est exacte, mais $11>8$ : un paquet de plus est possible. La division euclidienne s’écrit $\res{507=8\times63+3}$, avec $3<8$.','Comparer le reste au diviseur.','assert 507==8*62+11 and divmod(507,8)==(63,3)'),
E('Division par dix, cent, mille',r'Calculer $4\,500:100$, puis $38:10$, puis $7\,200:1\,000$.',r'Chaque chiffre descend de rangs : $\res{45}$ ; $\res{3{,}8}$ ; $\res{7{,}2}$.','Décaler les rangs vers la droite.','assert 4500/100==45 and Rational(38,10)==Rational("3.8") and Rational(7200,1000)==Rational("7.2")'),
E('Encadrer le quotient',r'Sans calculer le quotient exact, encadrer $250:7$ entre deux entiers consécutifs, puis calculer le quotient euclidien et le reste.',r'$7\times35=245$ et $7\times36=252$ : $\res{35<250:7<36}$. La division donne quotient $\res{35}$ et reste $\res5$.','Chercher deux multiples voisins du diviseur.','assert 7*35==245 and 7*36==252 and divmod(250,7)==(35,5)'),
E('L’erreur de virgule',r'Sami calcule $14{,}4:6=2{,}04$. Vérifier par la multiplication, expliquer l’erreur, corriger.',r'$2{,}04\times6=12{,}24\ne14{,}4$ : faux. Les 24 dixièmes donnent 4 dixièmes au quotient, pas 0 puis 4 : $14{,}4:6=\res{2{,}4}$ ; contrôle : $2{,}4\times6=14{,}4$.','Contrôler tout quotient par la multiplication.','assert Rational("2.04")*6==Rational("12.24") and Rational("14.4")/6==Rational("2.4")'),
E('La course en relais',r'Une équipe doit parcourir 15 km en 4 relais de même longueur. Quelle distance chaque coureur parcourt-il ?',r'$15:4=\res{3{,}75}$ km chacun. Contrôle : $3{,}75\times4=15$ km. Le quotient décimal convient, car une distance se partage exactement.','Poursuivre la division après la virgule.','assert Rational(15,4)==Rational("3.75")'),
E('Les packs d’eau',r'Un magasin reçoit 1\,350 bouteilles à ranger par packs de 8.'+Q(r'Combien de packs complets prépare-t-on ?',r'Combien de bouteilles restent seules ?',r'Combien manque-t-il de bouteilles pour un pack de plus ?'),r'$1\,350=8\times168+6$ : $\res{168}$ packs et $\res6$ bouteilles seules. Il manque $8-6=\res2$ bouteilles pour un pack de plus.','Faire parler le reste.','assert divmod(1350,8)==(168,6) and 8-6==2'),
E('Le ruban partagé',r'Un ruban de $9{,}6$ m est coupé en 8 morceaux identiques. Quelle est la longueur d’un morceau, en mètres puis en centimètres ?',r'$9{,}6:8=\res{1{,}2}$ m, car 96 dixièmes partagés en 8 font 12 dixièmes. En centimètres : $\res{120}$ cm.','Penser le dividende en dixièmes.','assert Rational("9.6")/8==Rational("1.2") and Rational("1.2")*100==120'),
E('La cagnotte des quatre',r'Quatre amis se partagent équitablement une cagnotte de 58 euros, en utilisant aussi les centimes. Combien reçoit chacun ? Vérifier que le partage rend bien toute la cagnotte.',r'$58:4=\res{14{,}50}$ euros chacun : 14 euros, puis 2 euros restants qui font 200 centimes, soit 50 centimes chacun. Contrôle : $14{,}50\times4=58$ euros.','Convertir le reste en centimes.','assert Rational(58,4)==Rational("14.50") and Rational("14.50")*4==58'),
E('Un partage impossible ?',r'Lila veut partager exactement 10 mètres de ficelle en 3 morceaux de même longueur, en écrivant la mesure en mètres. Que se passe-t-il ? Proposer une réponse raisonnable au centimètre près.',r'La division ne s’arrête pas : $10:3=3{,}33\ldots$ ; aucun nombre à deux décimales ne convient exactement. Au centimètre près, chaque morceau mesure environ $\res{3{,}33}$ m, et il reste un centimètre à répartir : $3\times3{,}33=9{,}99$. Certains partages n’ont pas d’écriture décimale exacte.','Arrêter la division au rang demandé et le dire.','assert 3*Rational("3.33")==Rational("9.99") and Rational(10,3)!=Rational("3.33")')
],reperes=['Division euclidienne contrôlée','Quotient décimal exact','Choisir le quotient utile','Partages et problèmes'],deco='calcul')

chapitre(5,'regularites','Égalités, programmes et suites','1 · Nombres entiers et calculs',
'Nombres cachés · Programmes de calcul · Motifs',
['Compléter des égalités et trouver des nombres cachés.','Exécuter et produire des programmes de calcul.','Prolonger des suites et calculer une étape lointaine.'],
['Les quatre opérations et le sens du signe égal.'],[
page(1,'Des égalités et des programmes',
bloc('definition',r'Le signe $=$ relie deux écritures du même nombre : $178-\square=6\times8$ se résout en calculant d’abord $6\times8=48$, puis $\square=178-48=130$.'),
r'@FIG:prog-cours@',
bloc('exemple',r'Exécuter le programme avec 6 : $6+2=8$ ; $8\times4=32$ ; $32-3=29$. Avec 10 : $12\times4=48$ ; $48-3=45$. Pour remonter un programme, on défait chaque étape en sens inverse : si le résultat est 29, on calcule $29+3=32$, puis $32:4=8$, puis $8-2=6$.'),
bloc('savoirfaire',r'Produire un programme, c’est choisir des étapes qui transforment l’entrée en la sortie voulue : passer de 5 à 26 peut s’écrire « multiplier par 5, ajouter 1 ». Tester ensuite son programme sur plusieurs nombres.','Inventer un programme'),
bloc('attention',r'L’ordre des étapes compte : « ajouter 2 puis multiplier par 4 » transforme 6 en 32 ; « multiplier par 4 puis ajouter 2 » transforme 6 en 26.')),
page(2,'Des suites à prolonger',
bloc('propriete',r'Une suite suit une règle. Additive : $7 ;\ 15 ;\ 23$ (on ajoute 8). Multiplicative : $7 ;\ 14 ;\ 28$ (on double). Une règle peut combiner : dans $7 ;\ 15 ;\ 31 ;\ 63$, chaque terme est le double du précédent plus 1.'),
bloc('savoirfaire',r'Dans une suite de motifs, compter ce qui change à chaque étape. Si l’étape 1 compte 5 carreaux et que chaque étape ajoute 4 carreaux, l’étape 10 compte $5+9\times4=41$ carreaux : neuf ajouts après la première étape.','Atteindre une étape lointaine'),
bloc('exemple',r'Étape inverse : quelle étape utilise 33 carreaux ? $33-5=28$, soit $28:4=7$ ajouts : c’est l’étape 8. Le calcul remplace le dessin de toutes les étapes.'),
bloc('attention',r'Toujours vérifier la règle sur plusieurs termes : $2 ;\ 4$ peut continuer en $6$ (ajouter 2) ou en $8$ (doubler). Deux termes ne suffisent pas à fixer une règle.'))
],[
E('Égalités à trous',r'Compléter : $178-\square=6\times8$ ; $\square:4=25$ ; $9\times\square=630$.',r'$6\times8=48$ puis $178-48=\res{130}$. Ensuite $25\times4=\res{100}$. Enfin $630:9=\res{70}$.','Calculer d’abord le côté connu.','assert 178-130==48 and 100//4==25 and 9*70==630'),
E('Exécuter le programme',r'Exécuter avec 6, puis avec 10 : choisir un nombre ; ajouter 2 ; multiplier par 4 ; retirer 3.',r'Avec 6 : $6+2=8$, $8\times4=32$, $32-3=\res{29}$. Avec 10 : $12\times4=48$, $48-3=\res{45}$.','Suivre les étapes dans l’ordre.','assert (6+2)*4-3==29 and (10+2)*4-3==45',figure='prog-2'),
E('Remonter le programme',r'Le programme « multiplier par 3 ; ajouter 6 ; multiplier par 2 » affiche 48. Quel nombre a été choisi ?',r'On remonte : $48:2=24$ ; $24-6=18$ ; $18:3=\res6$. Contrôle : $(6\times3+6)\times2=48$.','Défaire les étapes en sens inverse.','assert (6*3+6)*2==48 and (48//2-6)//3==6'),
E('Deux programmes, deux sorties',r'Comparer les sorties des programmes « ajouter 2 puis multiplier par 4 » et « multiplier par 4 puis ajouter 2 », pour l’entrée 6, puis pour l’entrée 10.',r'Premier programme : $\res{32}$ puis $\res{48}$. Second : $6\times4+2=\res{26}$ puis $10\times4+2=\res{42}$. L’ordre des étapes change la sortie.','Tester chaque programme séparément.','assert (6+2)*4==32 and 6*4+2==26 and (10+2)*4==48 and 10*4+2==42'),
E('La règle de la suite',r'Donner la règle et les deux termes suivants : $7 ;\ 15 ;\ 23 ;\ 31 ;\ \ldots$, puis $5 ;\ 10 ;\ 20 ;\ 40 ;\ \ldots$',r'Première suite : on ajoute 8 ; suivent $\res{39}$ et $\res{47}$. Seconde : chaque terme double ; suivent $\res{80}$ et $\res{160}$.','Comparer les écarts, puis les rapports.','assert 15-7==23-15==8 and 31+8==39 and 40*2==80'),
E('Double plus un',r'Vérifier que la suite $7 ;\ 15 ;\ 31 ;\ 63$ suit la règle « doubler puis ajouter 1 », puis donner les deux termes suivants.',r'$7\times2+1=15$ ; $15\times2+1=31$ ; $31\times2+1=63$ : la règle convient. Ensuite : $63\times2+1=\res{127}$, puis $127\times2+1=\res{255}$.','Tester la règle sur chaque passage.','assert 7*2+1==15 and 15*2+1==31 and 31*2+1==63 and 63*2+1==127 and 127*2+1==255'),
E('Le nombre caché',r'Trouver le nombre caché : $\square\times6-7=41$.',r'Avant de retirer 7, le produit valait $41+7=48$ ; avant de multiplier, le nombre était $48:6=\res8$. Contrôle : $8\times6-7=41$.','Remonter les opérations une à une.','assert 8*6-7==41'),
E('Produire un programme',r'Écrire un programme de calcul en deux étapes qui transforme 4 en 23, puis un autre, différent, qui transforme aussi 4 en 23.',r'Par exemple « multiplier par 5, ajouter 3 » : $4\times5+3=\res{23}$. Autre programme en deux étapes : « multiplier par 6, retirer 1 » : $4\times6-1=\res{23}$. Plusieurs chemins mènent à la même sortie.','Partir de la sortie et chercher un produit proche.','assert 4*5+3==23 and 4*6-1==23'),
E('La suite qui zigzague',r'Donner les trois termes suivants : $50 ;\ 59 ;\ 56 ;\ 65 ;\ 62 ;\ 71 ;\ \ldots$',r'La règle alterne $+9$ puis $-3$. Après 71 : $71-3=\res{68}$, puis $68+9=\res{77}$, puis $77-3=\res{74}$.','Observer les écarts un pas sur deux.','assert 59-50==9 and 59-56==3 and 71-3==68 and 68+9==77 and 77-3==74'),
E('Des symboles cohérents',r'Les mêmes symboles cachent les mêmes nombres : $\triangle+\triangle+\triangle=27$ et $\triangle+\bullet=17$. Trouver les deux nombres.',r'Trois triangles font 27 : $\triangle=\res9$. Alors $9+\bullet=17$ donne $\bullet=\res8$.','Résoudre d’abord l’égalité à un seul symbole.','assert 9+9+9==27 and 9+8==17'),
E('Le motif qui grandit',r'Un motif compte 5 carreaux à l’étape 1 et gagne 4 carreaux à chaque étape.'+Q(r'Combien de carreaux à l’étape 10 ?',r'À quelle étape le motif compte-t-il exactement 33 carreaux ?'),r'Étape 10 : neuf ajouts après la première : $5+9\times4=\res{41}$ carreaux. Pour 33 carreaux : $33-5=28$, soit $28:4=7$ ajouts : étape $\res8$. Contrôle : $5+7\times4=33$.','Compter les ajouts depuis l’étape 1.','assert 5+9*4==41 and (33-5)//4==7 and 5+7*4==33',figure='motifs-11'),
E('Les tee-shirts, suite',r'Un tee-shirt coûte 12 euros, la livraison 5 euros quel que soit le nombre acheté. Le prix pour $N$ tee-shirts s’écrit $(N\times12)+5$. Calculer le prix pour 7 tee-shirts, puis trouver $N$ pour un prix de 125 euros.',r'Pour 7 : $7\times12+5=\res{89}$ euros. Pour 125 euros : les tee-shirts coûtent $125-5=120$ euros, donc $N=120:12=\res{10}$.','Utiliser la formule dans les deux sens.','assert 7*12+5==89 and (125-5)//12==10 and 10*12+5==125'),
E('Le tableau de la machine',r'Une machine applique le même programme à chaque entrée : $3\to17$ ; $5\to27$ ; $8\to42$. Trouver le programme, puis la sortie pour 20.'+tableau(['Entrée','3','5','8','20'],[['Sortie','17','27','42','?']]),r'D’une entrée à l’autre, la sortie monte de 5 par unité d’entrée : essai « multiplier par 5, ajouter 2 » : $3\times5+2=17$ ; $5\times5+2=27$ ; $8\times5+2=42$ : la règle convient. Pour 20 : $20\times5+2=\res{102}$.','Tester une règle sur toutes les lignes du tableau.','assert 3*5+2==17 and 5*5+2==27 and 8*5+2==42 and 20*5+2==102'),
E('Vrai ou faux ?',r'Nora affirme : « La suite $2 ;\ 4 ;\ \ldots$ continue forcément par 6. » Donner deux suites différentes qui commencent par 2 puis 4, avec leurs règles.',r'« Ajouter 2 » donne $2 ;\ 4 ;\ \res6 ;\ 8$. « Doubler » donne $2 ;\ 4 ;\ \res8 ;\ 16$. Deux termes ne suffisent pas : l’affirmation est $\res{\text{fausse}}$. Une règle se vérifie sur plusieurs passages.','Chercher deux règles compatibles avec le début.','assert 4+2==6 and 4*2==8'),
E('Le défi du professeur',r'Un professeur écrit : « $\square\times\square=36$ et $\square$ est pair. » Trouver toutes les valeurs possibles du nombre caché, sachant qu’un même symbole cache le même nombre.',r'Le nombre multiplié par lui-même donne 36 : $6\times6=36$. Le candidat 6 est pair : $\square=\res6$. C’est la seule solution entière positive paire.','Chercher un nombre multiplié par lui-même.','assert 6*6==36 and 6%2==0')
],reperes=['Égalités et nombres cachés','Programmes : exécuter et produire','Suites de nombres','Motifs et étapes lointaines'],deco='algorithmique')
